cd /home/reid/1cfe/fusion-tea-stellarator-mbse-demo
python3 -c "
import json
a=json.load(open('/tmp/wi027_recap.snapshot.json'))       # recaptured at candidate
b=json.load(open('exploration/stellarator_e2e/stellarator.snapshot.json'))  # committed
def walk(pa, pb, path=''):
    if type(pa)!=type(pb):
        print(f'{path}: TYPE {type(pa).__name__} vs {type(pb).__name__}'); return
    if isinstance(pa,dict):
        for k in sorted(set(pa)|set(pb)):
            if k not in pa: print(f'{path}.{k}: only in committed')
            elif k not in pb: print(f'{path}.{k}: only in recap')
            else: walk(pa[k],pb[k],f'{path}.{k}')
    elif isinstance(pa,list):
        if len(pa)!=len(pb): print(f'{path}: LEN {len(pa)} vs {len(pb)}'); return
        for i,(x,y) in enumerate(zip(pa,pb)): walk(x,y,f'{path}[{i}]')
    else:
        if pa!=pb: print(f'{path}: {repr(pa)[:80]} != {repr(pb)[:80]}')
walk(a,b)
" 2>&1 | head -40

